package dev.zomboidmelee.boxing;import net.irisshaders.iris.Iris;import net.irisshaders.iris.pipeline.IrisRenderingPipeline;
public class IrisDepthChecks39 {static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}public static void main(String[]a){LaserLate37.depth=92;ok(LaserLate37.irisDepth()==0,"no active pipeline uses fallback");Iris.MANAGER.pipeline=new Object();ok(LaserLate37.irisDepth()==0,"vanilla pipeline does not probe private fields");var p=new IrisRenderingPipeline();Iris.MANAGER.pipeline=p;for(int i=1;i<1001;i++){p.targets().id=i;ok(LaserLate37.irisDepth()==i,"current Iris pre-hand texture reused directly, including after recreation");}ok(LaserLate37.depth==92,"borrowed texture never becomes owned allocation");p.targets().destroyed=true;ok(LaserLate37.irisDepth()==0,"destroyed target safely falls back");Iris.MANAGER.pipeline=null;ok(LaserLate37.irisDepth()==0,"pack unload drops borrowed reference");System.out.println("IRIS_NATIVE_DEPTH_RELOAD_LIFECYCLE_BORROWED_OWNERSHIP_CHECKS="+n);}}
